def history_seal_cutoff_path(agent: str) -> Path:
    return _agent_dir(agent) / f"{agent}_history_seal_cutoff"


def load_history_seal_cutoff(agent: str) -> int:
    """主人封存水位：bus_id <= cutoff 一律视为已结案（不 wake / 不入未结清单）。"""
    path = history_seal_cutoff_path(agent)
    if not path.is_file():
        return 0
    try:
        return int(path.read_text(encoding="utf-8").strip() or "0")
    except ValueError:
        return 0


def save_history_seal_cutoff(agent: str, cutoff: int) -> int:
    """抬升历史封存水位（只增不减）。"""
    cur = load_history_seal_cutoff(agent)
    if cutoff > cur:
        history_seal_cutoff_path(agent).write_text(str(cutoff), encoding="utf-8")
        return cutoff
    return cur


def bus_is_closed(agent: str, bus_id: int) -> bool:
    """已正式 reply 结案、processed 标记，或落在历史封存水位内。"""
    if bus_id > 0 and bus_id <= load_history_seal_cutoff(agent):
        return True
    return has_reply(agent, bus_id) or is_processed(agent, bus_id)

